param([string]$RosterPath,[switch]$SharedTeamPackage,[string]$Root=(Join-Path $env:LOCALAPPDATA 'G6\RabbitMQ\g5-onboarding'))
$ErrorActionPreference='Stop';$vaultPath=Join-Path $Root 'admin-vault.dpapi.json';if(-not(Test-Path $vaultPath)){throw 'Shared-key vault is missing; run the homologation-gated key preparation first.'};$vault=Get-Content -Raw -LiteralPath $vaultPath|ConvertFrom-Json
if($vault.format -cne 'G5-onboarding-DPAPI-v2'-or-not$vault.sshIdentity){throw 'A valid G5 shared SSH identity is required.'}
$credentialPath=Join-Path $Root 'rabbitmq-credential.dpapi.xml';if(-not(Test-Path $credentialPath)){throw 'Run the homologation-gated G5 RabbitMQ credential provisioning first.'}
$roster=if($SharedTeamPackage){@([pscustomobject]@{Nombre='Equipo G5 (paquete grupal pendiente de entrega)';Login='g5_equipo';EstadoHomologacion='ACEPTACION_COMUNICADA_HOMOLOGACION_FORMAL_PENDIENTE';ReferenciaHomologacion=''})}else{@(Import-Csv -LiteralPath $RosterPath)};if($roster.Count-eq 0-or@($roster|Where-Object {(-not $SharedTeamPackage-and($_.EstadoHomologacion -cne 'HOMOLOGADO'-or[string]::IsNullOrWhiteSpace($_.ReferenciaHomologacion)))-or$_.Login-notmatch'^g5_[a-z0-9][a-z0-9_-]{1,30}$'-or[string]::IsNullOrWhiteSpace($_.Nombre)}).Count-gt 0-or@($roster.Login|Sort-Object -Unique).Count-ne $roster.Count){throw 'Package generation requires a unique recipient roster; individual packages require formal homologation evidence.'}
$ssh=$vault.sshIdentity;if(-not(Test-Path $ssh.KeyPath)-or-not(Test-Path $ssh.PublicKeyPath)){throw 'Shared SSH key pair is incomplete.'};$credential=Import-Clixml $credentialPath;$rabbitPassword=[Net.NetworkCredential]::new('', $credential).Password;$iterations=600000
foreach($r in $roster){$member=@($vault.members|Where-Object Login -CEQ $r.Login);if($member.Count-ne 1){throw "Missing unique package-password entry for $($r.Login)."};$m=$member[0];if(Test-Path $m.PackagePath){throw "Encrypted package already exists for $($r.Login); refusing overwrite or rotation."};$files=[Collections.Generic.Dictionary[string,byte[]]]::new([StringComparer]::Ordinal)
  $files['ssh/g5_tunnel']=[IO.File]::ReadAllBytes($ssh.KeyPath);$files['ssh/g5_tunnel.pub']=[IO.File]::ReadAllBytes($ssh.PublicKeyPath)
  $meta=[ordered]@{Name=$r.Nombre;Login=$r.Login;SshLogin='g5_tunnel';KeyName='g5_tunnel';Fingerprint=$ssh.Fingerprint;Port=5673;Vhost='g6-productos-ofertas';SshIdentityShared=$true};$files['developer.json']=[Text.UTF8Encoding]::new($false).GetBytes(($meta|ConvertTo-Json -Compress))
  $files['ssh-config']=[Text.UTF8Encoding]::new($false).GetBytes("Host g5-dev`n    HostName 157.137.205.218`n    User g5_tunnel`n    Port 22`n    IdentityFile ~/.ssh/g5_tunnel`n    IdentitiesOnly yes`n    ForwardAgent no`n    RequestTTY no`n    ServerAliveInterval 15`n    ServerAliveCountMax 3`n    ExitOnForwardFailure yes`n")
  foreach($f in @('Start-G5RabbitMqTunnel.ps1','Test-G5RabbitMqTunnel.ps1','Test-G5RabbitMqTunnelReconnect.ps1','verify-g5-ventas-amqp.mjs')){$files["scripts/$f"]=[IO.File]::ReadAllBytes((Join-Path $PSScriptRoot $f))};foreach($f in @('Test-G5DeveloperAccess.ps1','Set-G5DeveloperRabbitMqUrl.ps1')){$files["install/$f"]=[IO.File]::ReadAllBytes((Join-Path $PSScriptRoot $f))};$files['templates/g5_ventas.env.example']=[IO.File]::ReadAllBytes((Join-Path $PSScriptRoot 'templates\g5_ventas.env.example'))
  $keySecure=ConvertTo-SecureString $ssh.ProtectedKeyPassphrase;$files['secrets/key-passphrase.txt']=[Text.UTF8Encoding]::new($false).GetBytes([Net.NetworkCredential]::new('', $keySecure).Password);$keySecure.Dispose();$files['secrets/credentials.json']=[Text.UTF8Encoding]::new($false).GetBytes((@{username='g5_ventas';vhost='g6-productos-ofertas';password=$rabbitPassword}|ConvertTo-Json -Compress))
  $mem=[IO.MemoryStream]::new();$zip=[IO.Compression.ZipArchive]::new($mem,[IO.Compression.ZipArchiveMode]::Create,$true);foreach($name in $files.Keys){$e=$zip.CreateEntry($name,[IO.Compression.CompressionLevel]::Optimal);$s=$e.Open();$s.Write($files[$name],0,$files[$name].Length);$s.Dispose()};$zip.Dispose();$plain=$mem.ToArray();$buf=$mem.GetBuffer();[Security.Cryptography.CryptographicOperations]::ZeroMemory($buf);$mem.Dispose()
  $pkgSecure=ConvertTo-SecureString $m.ProtectedPackagePassword;$pkgPassword=[Net.NetworkCredential]::new('', $pkgSecure).Password;$salt=[Security.Cryptography.RandomNumberGenerator]::GetBytes(16);$nonce=[Security.Cryptography.RandomNumberGenerator]::GetBytes(12);$key=[Security.Cryptography.Rfc2898DeriveBytes]::Pbkdf2($pkgPassword,$salt,$iterations,[Security.Cryptography.HashAlgorithmName]::SHA256,32);$header=[byte[]]::new(37);[Array]::Copy([Text.Encoding]::ASCII.GetBytes('G5PK1'),0,$header,0,5);[Array]::Copy($salt,0,$header,5,16);[Array]::Copy([BitConverter]::GetBytes([int]$iterations),0,$header,21,4);[Array]::Copy($nonce,0,$header,25,12);$cipher=[byte[]]::new($plain.Length);$tag=[byte[]]::new(16);$aes=[Security.Cryptography.AesGcm]::new($key,16);$aes.Encrypt($nonce,$plain,$cipher,$tag,$header);$aes.Dispose();$out=[IO.MemoryStream]::new();$out.Write($header);$out.Write($cipher);$out.Write($tag);$pkg=$out.ToArray();$out.Dispose();[IO.File]::WriteAllBytes($m.PackagePath,$pkg)
  $installerSource=Join-Path $PSScriptRoot 'Install-G5DeveloperPackage.ps1';Copy-Item $installerSource $m.InstallerPath -Force
  $owner=[Security.Principal.WindowsIdentity]::GetCurrent().Name;icacls (Join-Path $Root 'packages') /inheritance:r /grant:r "$owner`:(OI)(CI)F" 'NT AUTHORITY\SYSTEM:(OI)(CI)F'|Out-Null;foreach($protectedFile in @($m.PackagePath,$m.InstallerPath)){icacls $protectedFile /inheritance:r /grant:r "$owner`:(F)" 'NT AUTHORITY\SYSTEM:(F)'|Out-Null}
  foreach($a in @($plain,$buf,$key,$cipher,$tag,$pkg)){if($a -is [byte[]]){[Security.Cryptography.CryptographicOperations]::ZeroMemory($a)}};foreach($a in $files.Values){[Security.Cryptography.CryptographicOperations]::ZeroMemory($a)};$pkgPassword=$null;$pkgSecure.Dispose();Write-Output "$($r.Login): encrypted recipient package prepared; SHA-256 $((Get-FileHash -Algorithm SHA256 $m.PackagePath).Hash)."
}
$rabbitPassword=$null;$credential.Dispose()
